               class="flex items-center gap-3 rounded-xl px-3 py-2 text-sm font-semibold transition {{ $active ? 'bg-brand-500 text-white shadow-lg shadow-brand-900/40' : 'text-white/70 hover:bg-white/10 hover:text-white' }}">
